const routeErrors = [];
const contextIsObject = $json.context !== null && typeof $json.context === 'object' && !Array.isArray($json.context);
const context = contextIsObject ? $json.context : {};
if ($json.schema_version !== '1.0') routeErrors.push('Invalid schema_version: expected 1.0.');
if ($json.route !== 'command.new') routeErrors.push('Invalid route: expected command.new.');
if ($json.status !== 'ready') routeErrors.push('Invalid status: expected ready.');
if ($json.is_valid !== true) routeErrors.push('Input contract must be valid.');
if (!contextIsObject) routeErrors.push('Invalid context: expected an object.');
if (context.command !== 'new') routeErrors.push('Invalid context.command: expected new.');
if (!Array.isArray(context.command_args)) routeErrors.push('context.command_args must be an array.');
if (typeof context.argument_text !== 'string') routeErrors.push('context.argument_text must be a string.');
return [{ json: { ...$json, route_valid: routeErrors.length === 0, route_errors: routeErrors } }];

const context = $json.context && typeof $json.context === 'object' && !Array.isArray($json.context) ? $json.context : {};
const commandArgs = Array.isArray(context.command_args) ? context.command_args : [];
const argumentText = typeof context.argument_text === 'string' ? context.argument_text.trim() : '';
let novelTitleRaw = '';
let novelGenreRaw = '';
if (commandArgs.length > 0) {
  novelTitleRaw = commandArgs[0] == null ? '' : String(commandArgs[0]);
  novelGenreRaw = commandArgs.length > 1 && commandArgs[1] != null ? String(commandArgs[1]) : '';
} else if (argumentText) {
  novelTitleRaw = argumentText;
}
return [{ json: { ...$json, novel_title_raw: novelTitleRaw, novel_genre_raw: novelGenreRaw } }];

const normalizeSpaces = (value) => String(value ?? '').trim().replace(/\s+/gu, ' ');
const quotePairs = new Map([['"','"'],["'","'"],['“','”'],['‘','’'],['「','」'],['『','』']]);
const unwrap = (value) => {
  const normalized = normalizeSpaces(value);
  const closing = quotePairs.get(normalized[0]);
  return closing && normalized.length >= 2 && normalized.endsWith(closing)
    ? normalizeSpaces(normalized.slice(1, -closing.length))
    : normalized;
};
return [{ json: { ...$json, novel_title: unwrap($json.novel_title_raw), novel_genre: unwrap($json.novel_genre_raw) } }];

const validationErrors = [...($json.route_errors ?? [])];
const titleLength = Array.from($json.novel_title ?? '').length;
const genreLength = Array.from($json.novel_genre ?? '').length;
if (titleLength < 1) validationErrors.push('Novel title is required.');
else if (titleLength > 120) validationErrors.push('Novel title must not exceed 120 characters.');
if (genreLength > 40) validationErrors.push('Novel genre must not exceed 40 characters.');
return [{ json: { ...$json, is_valid: validationErrors.length === 0, validation_errors: validationErrors } }];

function uuidHelper() {
  let timestamp = Date.now();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (token) => {
    const randomValue = (timestamp + Math.random() * 16) % 16 | 0;
    timestamp = Math.floor(timestamp / 16);
    return (token === 'x' ? randomValue : (randomValue & 0x3) | 0x8).toString(16);
  });
}
if ($json.is_valid !== true) return [{ json: { ...$json, novel_uuid: '' } }];
return [{ json: { ...$json, novel_uuid: `NOV-${uuidHelper().replace(/-/g, '').slice(0, 8)}` } }];

if ($json.is_valid !== true) return [{ json: { ...$json, novel_slug: '' } }];
const asciiSlug = $json.novel_title.normalize('NFKD').replace(/[\u0300-\u036f]/gu, '').toLowerCase()
  .replace(/[^a-z0-9]+/gu, '-').replace(/^-+|-+$/gu, '').slice(0, 80).replace(/-+$/gu, '');
const suffix = $json.novel_uuid.replace(/^NOV-/u, '').toLowerCase();
return [{ json: { ...$json, novel_slug: asciiSlug || `novel-${suffix}` } }];

if ($json.is_valid !== true) return [{ json: { ...$json, metadata_draft: null } }];
const context = $json.context;
const timestamp = new Date().toISOString();
const toNumber = (value) => { const number = Number(value); return Number.isFinite(number) ? number : 0; };
return [{ json: { ...$json, metadata_draft: {
  novel_uuid: $json.novel_uuid, novel_id: null, novel_slug: $json.novel_slug,
  novel_title: $json.novel_title, novel_genre: $json.novel_genre, novel_status: 'draft',
  schema_version: '1.0', workflow_version: '2.0', created_at: timestamp, updated_at: timestamp,
  created_by: 'Novel Studio WF-002', telegram_update_id: toNumber(context.telegram_update_id),
  telegram_chat_id: toNumber(context.telegram_chat_id), telegram_user_id: toNumber(context.telegram_user_id),
  received_at: typeof context.received_at === 'string' ? context.received_at : '',
} } }];

if ($json.is_valid !== true) {
  const context = $json.context && typeof $json.context === 'object' ? $json.context : {};
  const toNumber = (value) => { const number = Number(value); return Number.isFinite(number) ? number : 0; };
  return [{ json: { is_valid: false, validation_errors: $json.validation_errors ?? [], novel: null, output_context: {
    telegram_update_id: toNumber(context.telegram_update_id), telegram_chat_id: toNumber(context.telegram_chat_id),
    telegram_user_id: toNumber(context.telegram_user_id), received_at: typeof context.received_at === 'string' ? context.received_at : '',
  } } }];
}
const m = $json.metadata_draft;
return [{ json: { is_valid: true, validation_errors: [], novel: {
  novel_uuid: m.novel_uuid, novel_id: m.novel_id, novel_slug: m.novel_slug,
  novel_title: m.novel_title, novel_genre: m.novel_genre, novel_status: m.novel_status,
  created_at: m.created_at, updated_at: m.updated_at, created_by: m.created_by,
}, output_context: {
  telegram_update_id: m.telegram_update_id, telegram_chat_id: m.telegram_chat_id,
  telegram_user_id: m.telegram_user_id, received_at: m.received_at,
} } }];

const isValid = $json.is_valid === true;
const novel = isValid && $json.novel && typeof $json.novel === 'object' ? $json.novel : {};
return [{ json: {
  schema_version: '1.0', workflow_version: '2.0', route: 'novel.metadata.created', target: 'WF-005',
  status: isValid ? 'ready' : 'error', is_valid: isValid,
  validation_errors: $json.validation_errors ?? [], novel: isValid ? $json.novel : null,
  novel_uuid: String(novel.novel_uuid ?? ''),
  novel_title: String(novel.novel_title ?? ''),
  genre: String(novel.genre ?? ''),
  context: $json.output_context,
} }];
